def row(
    row_id: str,
    category: str,
    gender: str,
    voice: str,
    emotion_type: str,
    tag: str,
    text: str,
) -> Dict[str, str]:
    return {
        "id": row_id,
        "category": category,
        "gender": gender,
        "voice": voice,
        "emotion_type": emotion_type,
        "tag": tag,
        "text": text,
    }


def r2(num: int, category: str, gender: str, emotion_type: str, tag: str, text: str) -> Dict[str, str]:
    voices = {
        "female": ["Callirrhoe", "Aoede", "Kore", "Despina", "Laomedeia", "Leda"],
        "male": ["Puck", "Charon", "Fenrir", "Orus", "Iapetus", "Algenib"],
    }
    voice = voices[gender][num % len(voices[gender])]
    label = emotion_type or category
    return row(f"manual_{num:04d}_{label}_{gender}", category, gender, voice, emotion_type, tag, text)


